const makeAnimTank = (exportName, name, frame1, frame31, options = {}) => {
    let duration = options.duration || 20;
    let prop = options.prop != null ? options.prop : true;
    let gunPositionA = options.gunPositionA || false;
    let gunPositionB = options.gunPositionB || false;
    let turretPositionA = options.turretPositionA || false;
    let turretPositionB = options.turretPositionB || false;
    defExport[`${exportName}0`] = structuredClone(frame1);
    defExport[`${exportName}0`].GUNS = structuredClone(frame1.GUNS || []);
    defExport[`${exportName}0`].TURRETS = frame1.TURRETS || [];
    defExport[`${exportName}0`].LABEL = name;
    defExport[`${exportName}31`] = structuredClone(frame31);
    defExport[`${exportName}31`].GUNS = structuredClone(frame31.GUNS || []);
    defExport[`${exportName}31`].TURRETS = frame31.TURRETS || [];
    defExport[`${exportName}31`].LABEL = name;
    let gunsA = defExport[`${exportName}0`].GUNS;
    let gunsB = defExport[`${exportName}31`].GUNS;
    let turretsA = defExport[`${exportName}0`].TURRETS;
    let turretsB = defExport[`${exportName}31`].TURRETS;
    for (let i = 1; i < 31; i++) {
        defExport[`${exportName}${i}`] = {
            PARENT: [defExport.genericTank],
            LABEL: name,
            GUNS: [],
            TURRETS: []
        }
        for (let j = 0; j < Math.max(gunsA.length, gunsB.length); j++) {
            if (j < Math.min(gunsA.length, gunsB.length)) {
                defExport[`${exportName}${i}`].GUNS.push({
                    POSITION: [
                        gunsA[j].POSITION[0] * (1 - i / 31) + gunsB[j].POSITION[0] * (i / 31),
                        gunsA[j].POSITION[1] * (1 - i / 31) + gunsB[j].POSITION[1] * (i / 31),
                        gunsA[j].POSITION[2] * (1 - i / 31) + gunsB[j].POSITION[2] * (i / 31),
                        gunsA[j].POSITION[3] * (1 - i / 31) + gunsB[j].POSITION[3] * (i / 31),
                        gunsA[j].POSITION[4] * (1 - i / 31) + gunsB[j].POSITION[4] * (i / 31),
                        gunsA[j].POSITION[5] * (1 - i / 31) + gunsB[j].POSITION[5] * (i / 31),
                        0
                    ],
                    PROPERTIES: {
                        SKIN: gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.SKIN || null : null,
                        COLOR: gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.COLOR || null : null,
                        COLOR_UNMIX: gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.COLOR_UNMIX || null : null
                    }
                });
            } else if (gunsA.length > gunsB.length) {
                defExport[`${exportName}${i}`].GUNS.push({
                    POSITION: [
                        gunsA[j].POSITION[0] * (1 - i / 31),
                        gunsA[j].POSITION[1] * (1 - i / 31),
                        gunsA[j].POSITION[2] * (1 - i / 31),
                        gunsA[j].POSITION[3] * (1 - i / 31),
                        gunsA[j].POSITION[4] * (1 - i / 31),
                        gunsA[j].POSITION[5],
                        0
                    ],
                    PROPERTIES: {
                        SKIN: gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.SKIN || null : null,
                        COLOR: gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.COLOR || null : null,
                        COLOR_UNMIX: gunsA[j].PROPERTIES ? gunsA[j].PROPERTIES.COLOR_UNMIX || null : null
                    }
                });
            } else {
                defExport[`${exportName}${i}`].GUNS.push({
                    POSITION: [
                        gunsB[j].POSITION[0] * (i / 31),
                        gunsB[j].POSITION[1] * (i / 31),
                        gunsB[j].POSITION[2] * (i / 31),
                        gunsB[j].POSITION[3] * (i / 31),
                        gunsB[j].POSITION[4] * (i / 31),
                        gunsB[j].POSITION[5],
                        0
                    ],
                    PROPERTIES: {
                        SKIN: gunsB[j].PROPERTIES ? gunsB[j].PROPERTIES.SKIN || null : null,
                        COLOR: gunsB[j].PROPERTIES ? gunsB[j].PROPERTIES.COLOR || null : null,
                        COLOR_UNMIX: gunsB[j].PROPERTIES ? gunsB[j].PROPERTIES.COLOR_UNMIX || null : null
                    }
                });
            }
        }
        if (prop) defExport[`${exportName}${i}`].GUNS.push({
            POSITION: [14, 3.5, 1, 0, 0, 0, 0],
            PROPERTIES: {
                COLOR: 245 + i
            }
        });
        posA = turretPositionA ? turretPositionA : turretsA;
        posB = turretPositionB ? turretPositionB : turretsB;
        for (let j = 0; j < Math.max(posA.length, posB.length); j++) {
            if (j < Math.min(posA.length, posB.length)) {
                defExport[`${exportName}${i}`].TURRETS.push({
                    POSITION: [
                        posA[j].POSITION[0] * (1 - i / 31) + posB[j].POSITION[0] * (i / 31),
                        posA[j].POSITION[1] * (1 - i / 31) + posB[j].POSITION[1] * (i / 31),
                        posA[j].POSITION[2] * (1 - i / 31) + posB[j].POSITION[2] * (i / 31),
                        posA[j].POSITION[3] * (1 - i / 31) + posB[j].POSITION[3] * (i / 31),
                        0,
                        posA[j].POSITION[5]
                    ],
                    TYPE: posA[j].TYPE
                });
            } else if (posA.length > posB.length) {
                defExport[`${exportName}${i}`].TURRETS.push({
                    POSITION: [
                        posA[j].POSITION[0] * (1 - i / 31),
                        posA[j].POSITION[1] * (1 - i / 31),
                        posA[j].POSITION[2] * (1 - i / 31),
                        posA[j].POSITION[3] * (1 - i / 31),
                        0,
                        posA[j].POSITION[5]
                    ],
                    TYPE: posA[j].TYPE
                });
            } else {
                defExport[`${exportName}${i}`].TURRETS.push({
                    POSITION: [
                        posB[j].POSITION[0] * (i / 31),
                        posB[j].POSITION[1] * (i / 31),
                        posB[j].POSITION[2] * (i / 31),
                        posB[j].POSITION[3] * (i / 31),
                        0,
                        posB[j].POSITION[5]
                    ],
                    TYPE: posB[j].TYPE
                });
            }
        }
    }
    if (prop) {
        defExport[`${exportName}0`].GUNS.push({
            POSITION: [14, 3.5, 1, 0, 0, 0, 0],
            PROPERTIES: {
                COLOR: 245
            }
        });
        defExport[`${exportName}31`].GUNS.push({
            POSITION: [14, 3.5, 1, 0, 0, 0, 0],
            PROPERTIES: {
                COLOR: 276
            }
        });
    }
    defExport[`${exportName}0`].GUNS.push({
        POSITION: [1, 1, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTING: combineStats([g.basic, g.fake, g.no_recoil]),
            TYPE: defExport.bullet,
            ALT_FIRE: true,
            ON_FIRE: (gun, gunInfo) => {
                for (let i = 1; i < 32; i++) setTimeout(() => {
                    if (gun.body.master.isAlive()) gun.body.master.define(Class[`${exportName}${i}`]);
                }, duration * i);
            }
        }
    });
    defExport[`${exportName}31`].GUNS.push({
        POSITION: [1, 1, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTING: combineStats([g.basic, g.fake, g.no_recoil]),
            TYPE: defExport.bullet,
            ALT_FIRE: true,
            ON_FIRE: (gun, gunInfo) => {
                for (let i = 1; i < 32; i++) setTimeout(() => {
                    if (gun.body.master.isAlive()) gun.body.master.define(Class[`${exportName}${31 - i}`]);
                }, duration * i);
            }
        }
    });
}
const makeHybrid = (type, name = -1, isYoukron = false) => {
    let output = JSON.parse(JSON.stringify(type)),
        gun = {
            POSITION: [7, 12, 1.2, 8, 0, 180, 0],
            PROPERTIES: {
                SHOOT_SETTINGS: combineStats([g.drone, g.weak]),
                TYPE: [defExport.drone, {
                    INDEPENDENT: true
                }],
                AUTOFIRE: true,
                SYNCS_SKILLS: true,
                STAT_CALCULATOR: gunCalcNames.drone,
                WAIT_TO_CYCLE: true,
                MAX_CHILDREN: isYoukron ? 5 : 3
            }
        };
    if (type.DANGER != null) output.DANGER = type.DANGER >= 7 ? type.DANGER : type.DANGER + 1;
    if (type.TURRETS != null) output.TURRETS = type.TURRETS;
    output.GUNS = type.GUNS == null ? [gun] : [...type.GUNS, gun];
    output.LABEL = name === -1 ? (isYoukron ? 'Youkron ' : 'Hybrid ') + type.LABEL : name;
    output.STAT_NAMES = statNames.generic;
    if (isYoukron) output.SHAPE = 9;
    return output;
};
