const makeAutoN = (type, sides = 3, name = -1, options = {}) => {
    if (options.swivel == null) options.swivel = false;
    if (options.color == null) options.color = 16;
    if (options.size == null) options.size = options.swivel ? 8 * (Math.pow(Math.sqrt(.625, 4), sides - 3)) + 1 : 10 * (Math.pow(Math.sqrt(.78, 4), sides - 3)) + 1;
    if (options.stats == null || options.stats === []) options.stats = [g.blank];
    if (options.x == null) options.x = options.swivel ? 7 : 9;
    let output = JSON.parse(JSON.stringify(type));
    defExport['autoNClone' + counters.autoNClone] = JSON.parse(JSON.stringify(type));
    let tank = defExport['autoNClone' + counters.autoNClone];
    tank.TURRETS = type.TURRETS;
    for (let i = 0; i < tank.GUNS.length; i++) try {
        let gun = tank.GUNS[i].PROPERTIES.SHOOT_SETTINGS,
            stats = [
                [gun.reload, gun.recoil, gun.shudder, gun.size, gun.health, gun.damage, gun.pen, gun.speed, gun.maxSpeed, gun.range, gun.density, gun.spray, gun.resist], g.auto, options.swivel ? [1.5, 1, 1, 1, .81, .765, .9, 1, 1, 1, 1, 1, 1] : g.blank
            ];
        for (let component of options.stats) stats.push(component);
        tank.GUNS[i].PROPERTIES.SHOOT_SETTINGS = combineStats(stats);
        defExport['autoNTurret' + counters.autoNTurret] = output.GUNS[i].PROPERTIES.TYPE;
        defExport['autoNTurret' + counters.autoNTurret].TURRETS = type.GUNS[i].PROPERTIES.TYPE.TURRETS;
        tank.GUNS[i].PROPERTIES.TYPE = defExport['autoNTurret' + counters.autoNTurret];
        counters.autoNTurret++;
    } catch (e) {}
    tank.DANGER = 'makeAutoN turret';
    let a = 0;
    const turret = a => ([{
        POSITION: [options.size, options.swivel ? 7 : 9, 0, a, options.swivel ? 360 : 360 / sides + 65, options.swivel ? 1 : 0],
        TYPE: [tank, {
            LABEL: '',
            BODY: {
                FOV: 2.5
            },
            CONTROLLERS: ['canRepel', 'onlyAcceptInArc', 'mapAltToFire', 'nearestDifferentMaster'],
            COLOR: options.color
        }]
    }]);
    if (type.DANGER != null) output.DANGER = (type.DANGER >= 7 || type.DANGER + sides - 1 >= 7) ? 7 : type.DANGER + sides - 1;
    output.TURRETS = [];
    for (let i = 0; i < sides; i++) output.TURRETS = output.TURRETS.concat(turret(i * (360 / sides)));
    output.LABEL = name === -1 ? type.LABEL + '-' + sides : name;
    output.FACING_TYPE = 'autospin';
    output.GUNS = [];
    counters.autoNClone++;
    return output;
};
const makeHivemind = (type, name = -1, options = {}) => {
    if (options.amount == null) options.amount = 2;
    if (options.width == null) options.width = 14;
    if (options.shape == null) options.shape = 0;
    if (options.color == null) options.color = 9;
    if (options.size == null) options.size = 21;
    //if (options.stats == null || options.stats === []) options.stats = g.blank;
    let output = JSON.parse(JSON.stringify(type)),
        input = JSON.parse(JSON.stringify(type));
    defExport['hiveClone' + counters.hiveClone] = JSON.parse(JSON.stringify(defExport.probe));
    let tank = defExport['hiveClone' + counters.hiveClone],
        hull = {
            POSITION: [options.size, 0, 0, 0, 360, 0],
            TYPE: [defExport.eggBossCircleProp, {
                SHAPE: options.shape,
                COLOR: options.color
            }]
        };
    tank.TURRETS = input.TURRETS == null ? [hull] : [...input.TURRETS, hull];
    if (input.GUNS != null) {
        tank.GUNS = input.GUNS;
        for (let i = 0; i < tank.GUNS.length; i++) try {
            let gun = tank.GUNS[i].PROPERTIES.SHOOT_SETTINGS;
            tank.GUNS[i].PROPERTIES.SHOOT_SETTINGS = combineStats([
                [gun.reload, gun.recoil, gun.shudder, gun.size, gun.health, gun.damage, gun.pen, gun.speed, gun.maxSpeed, gun.range, gun.density, gun.spray, gun.resist], g.half_reload, g.half_damage, g.less_damage, g.less_range
            ]);
            defExport['hiveProbe' + counters.hiveProbe] = type.GUNS[i].PROPERTIES.TYPE;
            defExport['hiveProbe' + counters.hiveProbe].ALWAYS_ACTIVE = true;
            tank.GUNS[i].PROPERTIES.TYPE = defExport['hiveProbe' + counters.hiveProbe];
            counters.hiveProbe++;
        } catch (e) {}
    } else tank.GUNS = [];
    let spawner = {
        POSITION: [2, options.width, 1, 0, 0, 180, 2],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.hivemind]),
            TYPE: tank,
            SYNCS_SKILLS: true,
            STAT_CALCULATOR: gunCalcNames.drone,
            MAX_CHILDREN: options.amount
        }
    };
    output.hivemindID = tank;
    output.DANGER = 7;
    output.TURRETS = type.TURRETS == null ? [hull] : [...type.TURRETS, hull];
    output.GUNS = type.GUNS == null ? [spawner] : [...type.GUNS, spawner];
    output.LABEL = name === -1 ? type.LABEL + 'mind' : name;
    counters.hiveClone++;
    return output;
};
