const makeFlank = (type, sides = 3, name = -1, options = {}) => {
    if (options.reload_delay == null) options.reload_delay = [];
    if (options.stats == null || options.stats === []) options.stats = [g.blank];
    if (options.angles == null) options.angles = [];
    let output = JSON.parse(JSON.stringify(type)),
        preGun = JSON.parse(JSON.stringify(type.GUNS)),
        aryGun = [];
    for (let i = 0; i < preGun.length; i++)
        if (options.angles[0] != undefined) preGun[i].POSITION[5] = options.angles[0];
    for (let i = 0; i < sides; i++) {
        for (let j = 0; j < preGun.length; j++) preGun[j].POSITION[6] = type.GUNS[j].POSITION[6] + (options.reload_delay[i] == undefined ? 0 : options.reload_delay[i]);
        aryGun.push(JSON.parse(JSON.stringify(preGun)));
        for (let j = 0; j < preGun.length; j++) preGun[j].POSITION[5] = options.angles[i + 1] == undefined ? preGun[j].POSITION[5] + 360 / sides : options.angles[i + 1];
    }
    output.GUNS = [];
    for (let i = 0; i < aryGun.length; i++) Array.prototype.push.apply(output.GUNS, aryGun[i]);
    for (let i = 0; i < output.GUNS.length; i++) try {
        let gun = output.GUNS[i].PROPERTIES.SHOOT_SETTINGS,
            stats = [
                [gun.reload, gun.recoil, gun.shudder, gun.size, gun.health, gun.damage, gun.pen, gun.speed, gun.maxSpeed, gun.range, gun.density, gun.spray, gun.resist], g.flank
            ];
        for (let component of options.stats) stats.push(component);
        output.GUNS[i].PROPERTIES.SHOOT_SETTINGS = combineStats(stats);
        defExport['makeFlank' + counters.flank] = output.GUNS[i].PROPERTIES.TYPE;
        output.GUNS[i].PROPERTIES.TYPE = defExport['makeFlank' + counters.flank];
        counters.flank++;
    } catch (e) {}
    if (type.DANGER != null) output.DANGER = type.DANGER >= 7 ? type.DANGER : type.DANGER + 1;
    output.LABEL = name === -1 ? 'Flank ' + type.LABEL : name;
    return output;
};
const makePara = (x, yy, name = -1, options = {}) => {
    if (options.c == null) options.c = 50;
    if (options.mul == null) options.mul = 2;
    if (options.cycle == null) options.cycle = 360;
    if (options.color == null) options.color = 25;
    if (options.stat == null) options.stat = g.blank;
    let bullet = JSON.parse(JSON.stringify(defExport.bullet)),
        output = JSON.parse(JSON.stringify(defExport.genericTank));
    bullet.GUNS = [];
    bullet.MOTION_TYPE = 'stopOnDeath';
    for (let i = 0; i < options.cycle; i += options.cycle / options.c) {
        let ex = eval(x),
            ey = eval(yy),
            spd = Math.hypot(ex, ey) * options.mul;
        bullet.GUNS.push({
            POSITION: [0, 18, 1, 10, 0, Math.atan2(ey, ex) * (180 / Math.PI), 1e99],
            PROPERTIES: {
                SHOOT_SETTINGS: combineStats([
                    [66, 1, .0000001, .25, 1, .07, 5, spd, spd, 2, 1, .0000001, 1], options.stat
                ]),
                TYPE: [defExport.bullet, {
                    PERSISTS_AFTER_DEATH: true
                }],
                LABEL: gunCalcNames.thruster,
                SHOOT_ON_DEATH: true
            }
        })
    };
    output.LABEL = name === -1 ? 'Parametic' : name;
    output.GUNS.push({
        POSITION: [18, 8, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([
                [66, 0, .1, 1, .0002, .2, 1, .000045, 2, 0, 1, 15, 1]
            ]),
            TYPE: bullet
        }
    }, {
        POSITION: [19, 3, 1, 0, 0, 0, 0],
        PROPERTIES: {
            COLOR: options.color
        }
    });
    return output;
};
