defExport.securityPounder = {
    PARENT: [defExport.genericTank],
    LABEL: 'Security Pounder',
    DANGER: 5,
    BODY: {
        ACCELERATION: base.ACCEL * .8
    },
    GUNS: [{
        POSITION: [20, 12, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.pound]),
            TYPE: defExport.bullet,
            CAN_SHOOT: true,
        }
    }],
    TOOLTIP: "Whenever you get damaged release a swarm of drones",
    ON_DAMAGED: function(me, them){
        for (let gun of me.guns) {
            gun.canShoot = !gun.canShoot
            if (gun.canShoot && global.utility.time()-gun.lastShot.time > 3000){
                fireGun(gun);
            }
            gun.canShoot = !gun.canShoot
        }
    }
};
defExport.securityDestroyer = {
    PARENT: [defExport.genericTank],
    LABEL: 'Security Destroyer',
    DANGER: 6,
    BODY: {
        ACCELERATION: base.ACCEL * .75
    },
    GUNS: [{
        POSITION: [21, 14, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.pound, g.destroy]),
            TYPE: defExport.bullet
        }
    }],
    TOOLTIP: "Whenever you get damaged release a swarm of drones",
    ON_DAMAGED: function(me, them){
        for (let gun of me.guns) {
            gun.canShoot = !gun.canShoot
            if (gun.canShoot && global.utility.time()-gun.lastShot.time > 3000){
                gun.fire(
                    gun.offset * Math.cos(gun.direction + gun.angle + gun.body.facing) + (1.35 * gun.length - gun.width * gun.settings.size / 2) * Math.cos(gun.angle + gun.body.facing),
                    gun.offset * Math.sin(gun.direction + gun.angle + gun.body.facing) + (1.35 * gun.length - gun.width * gun.settings.size / 2) * Math.sin(gun.angle + gun.body.facing),
                    gun.body.skill
                )
            }
            gun.canShoot = !gun.canShoot
        }
    }
};

