{
    // Builder/Constructor branch forward-offset tuning:
    // +2 for all branch classes except Constructor and Manufacturer.
    const addForwardOffsetToBranches = (roots, { exclude = [], offsetAdd = 2 } = {}) => {
        const visited = new Set();
        const excluded = new Set(exclude.filter(Boolean));
        const tuneTank = (tank) => {
            if (!tank || visited.has(tank)) return;
            visited.add(tank);
            const shouldTune = !excluded.has(tank);
            if (shouldTune && Array.isArray(tank.GUNS)) {
                for (const gun of tank.GUNS) {
                    if (!gun || !Array.isArray(gun.POSITION) || gun.POSITION.length < 4) continue;
                    if (!(gun.PROPERTIES && gun.PROPERTIES.SHOOT_SETTINGS)) continue;
                    if (Number.isFinite(gun.POSITION[3])) gun.POSITION[3] += offsetAdd;
                }
            }
            for (const key in tank) {
                if (!key.startsWith('UPGRADES_TIER_')) continue;
                if (!Array.isArray(tank[key])) continue;
                for (const next of tank[key]) tuneTank(next);
            }
        };
        for (const root of roots) tuneTank(root);
    };
    addForwardOffsetToBranches([defExport.builder, defExport.construct], {
        exclude: [defExport.construct, defExport.snipeConstruct],
        offsetAdd: 2
    });
}
{
    // Final per-class spawn-offset corrections.
    const adjustForwardOffset = (tank, delta) => {
        if (!tank || !Number.isFinite(delta) || !Array.isArray(tank.GUNS)) return;
        for (const gun of tank.GUNS) {
            if (!gun || !Array.isArray(gun.POSITION) || gun.POSITION.length < 4) continue;
            if (!(gun.PROPERTIES && gun.PROPERTIES.SHOOT_SETTINGS)) continue;
            if (Number.isFinite(gun.POSITION[3])) gun.POSITION[3] += delta;
        }
    };
    adjustForwardOffset(defExport.megaConstruct, 2); // Decalibrator
    adjustForwardOffset(defExport.annihilator, -1.5);
    adjustForwardOffset(defExport.destroyer, -1);
}

